    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpAcwsensor = ACWSensor()
        tmpAcwsensor.Init(buf, pos)
        return cls.InitFromObj(tmpAcwsensor)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpAcwsensor):
        x = ACWSensorT()
        x._UnPack(tmpAcwsensor)
        return x

    # ACWSensorT
    def _UnPack(self, ACWSensor):
        if ACWSensor is None:
            return
        self.SENSOR_ID = ACWSensor.SENSOR_ID()
        self.HOST_ID = ACWSensor.HOST_ID()
        self.PHENOMENOLOGY = ACWSensor.PHENOMENOLOGY()
        if not ACWSensor.ERROR_MODELSIsNone():
            self.ERROR_MODELS = []
            for i in range(ACWSensor.ERROR_MODELSLength()):
                if ACWSensor.ERROR_MODELS(i) is None:
                    self.ERROR_MODELS.append(None)
                else:
                    mEMErrorModel_ = MEMErrorModel.MEMErrorModelT.InitFromObj(ACWSensor.ERROR_MODELS(i))
                    self.ERROR_MODELS.append(mEMErrorModel_)
        if ACWSensor.CONSTRAINTS() is not None:
            self.CONSTRAINTS = ACWConstraintSet.ACWConstraintSetT.InitFromObj(ACWSensor.CONSTRAINTS())
        self.OBSERVATION_INTERVAL_S = ACWSensor.OBSERVATION_INTERVAL_S()
