    # ACWSensorT
    def Pack(self, builder):
        if self.SENSOR_ID is not None:
            SENSOR_ID = builder.CreateString(self.SENSOR_ID)
        if self.HOST_ID is not None:
            HOST_ID = builder.CreateString(self.HOST_ID)
        if self.ERROR_MODELS is not None:
            ERROR_MODELSlist = []
            for i in range(len(self.ERROR_MODELS)):
                ERROR_MODELSlist.append(self.ERROR_MODELS[i].Pack(builder))
            ACWSensorStartERROR_MODELSVector(builder, len(self.ERROR_MODELS))
            for i in reversed(range(len(self.ERROR_MODELS))):
                builder.PrependUOffsetTRelative(ERROR_MODELSlist[i])
            ERROR_MODELS = builder.EndVector()
        if self.CONSTRAINTS is not None:
            CONSTRAINTS = self.CONSTRAINTS.Pack(builder)
        ACWSensorStart(builder)
        if self.SENSOR_ID is not None:
            ACWSensorAddSENSOR_ID(builder, SENSOR_ID)
        if self.HOST_ID is not None:
            ACWSensorAddHOST_ID(builder, HOST_ID)
        ACWSensorAddPHENOMENOLOGY(builder, self.PHENOMENOLOGY)
        if self.ERROR_MODELS is not None:
            ACWSensorAddERROR_MODELS(builder, ERROR_MODELS)
        if self.CONSTRAINTS is not None:
            ACWSensorAddCONSTRAINTS(builder, CONSTRAINTS)
        ACWSensorAddOBSERVATION_INTERVAL_S(builder, self.OBSERVATION_INTERVAL_S)
        ACWSensorAddTRACK_DURATION_S(builder, self.TRACK_DURATION_S)
        ACWSensorAddREVISIT_INTERVAL_S(builder, self.REVISIT_INTERVAL_S)
        ACWSensorAddMAX_SIMULTANEOUS_TRACKS(builder, self.MAX_SIMULTANEOUS_TRACKS)
        ACWSensorAddREFERENCE_SNR_DB(builder, self.REFERENCE_SNR_DB)
        ACWSensorAddREFERENCE_RANGE_M(builder, self.REFERENCE_RANGE_M)
        ACWSensorAddREFERENCE_RCS_M2(builder, self.REFERENCE_RCS_M2)
        ACWSensorAddDETECTION_THRESHOLD_DB(builder, self.DETECTION_THRESHOLD_DB)
        ACWSensorAddRECEIVER_G_OVER_T_DB_PER_K(builder, self.RECEIVER_G_OVER_T_DB_PER_K)
        ACWSensorAddRECEIVER_BANDWIDTH_HZ(builder, self.RECEIVER_BANDWIDTH_HZ)
        ACWSensorAddLIMITING_MAGNITUDE(builder, self.LIMITING_MAGNITUDE)
        ACWSensorAddMAX_HOST_SUN_ELEVATION_RAD(builder, self.MAX_HOST_SUN_ELEVATION_RAD)
        ACWSensorAddFALSE_ALARM_RATE_PER_HOUR(builder, self.FALSE_ALARM_RATE_PER_HOUR)
        ACWSensorAddTRANSMIT_FREQUENCY_HZ(builder, self.TRANSMIT_FREQUENCY_HZ)
        ACWSensorAddHAS_PHENOMENOLOGY(builder, self.HAS_PHENOMENOLOGY)
        ACWSensorAddHAS_OBSERVATION_INTERVAL_S(builder, self.HAS_OBSERVATION_INTERVAL_S)
        ACWSensorAddHAS_TRACK_DURATION_S(builder, self.HAS_TRACK_DURATION_S)
        ACWSensorAddHAS_REVISIT_INTERVAL_S(builder, self.HAS_REVISIT_INTERVAL_S)
        ACWSensorAddHAS_MAX_SIMULTANEOUS_TRACKS(builder, self.HAS_MAX_SIMULTANEOUS_TRACKS)
        ACWSensorAddHAS_REFERENCE_SNR_DB(builder, self.HAS_REFERENCE_SNR_DB)
        ACWSensorAddHAS_REFERENCE_RANGE_M(builder, self.HAS_REFERENCE_RANGE_M)
        ACWSensorAddHAS_REFERENCE_RCS_M2(builder, self.HAS_REFERENCE_RCS_M2)
        ACWSensorAddHAS_DETECTION_THRESHOLD_DB(builder, self.HAS_DETECTION_THRESHOLD_DB)
        ACWSensorAddHAS_RECEIVER_G_OVER_T_DB_PER_K(builder, self.HAS_RECEIVER_G_OVER_T_DB_PER_K)
        ACWSensorAddHAS_RECEIVER_BANDWIDTH_HZ(builder, self.HAS_RECEIVER_BANDWIDTH_HZ)
