        ACWSensorAddHAS_FALSE_ALARM_RATE_PER_HOUR(builder, self.HAS_FALSE_ALARM_RATE_PER_HOUR)
        ACWSensorAddHAS_TRANSMIT_FREQUENCY_HZ(builder, self.HAS_TRANSMIT_FREQUENCY_HZ)
        ACWSensor = ACWSensorEnd(builder)
        return ACWSensor
